"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { ArrowUpRight, Bot, ChevronRight, CircleHelp, Database, Menu, Send, X } from "lucide-react";
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import websiteData from "@/data/website_data.json";
import modelInputs from "@/data/model_inputs.json";
import step2Data from "@/data/step2_workload_matrix.json";
import gpuTierAudit from "@/data/gpu_tier_matrix.json";
import requirementsData from "@/data/requirements_matrix.json";
import eligibilityRules from "@/data/eligibility_rules.json";
import candidateRegions from "@/data/candidate_regions.json";
import siteDueDiligence from "@/data/site_due_diligence.json";
import { calculatePhase1 } from "@/lib/phase1-model";
import { sections } from "@/lib/sections";

const path = (slug: string) => slug === "overview" ? "/" : `/${slug}`;

function Tag({ children }: { children: React.ReactNode }) { return <span className="tag">{children}</span>; }
function SectionHead({ eyebrow, title, note }: { eyebrow: string; title: string; note?: string }) {
  return <div className="section-head"><div className="eyebrow">{eyebrow}</div><h2>{title}</h2>{note && <p>{note}</p>}</div>;
}
function Placeholder({ label = "TBD", note }: { label?: string; note?: string }) { return <span className="placeholder" title={note || "Pending research"}>{label}</span>; }
function Panel({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <section className={`panel ${className}`}>{children}</section>; }
function Next({ slug, label }: { slug: string; label: string }) { return <Link className="next-link" href={path(slug)}><span>Next: {label}</span><ArrowUpRight size={18} /></Link>; }
function ResearchNote() { return <div className="research-note"><strong>ILLUSTRATIVE · ASSUMPTION / ESTIMATE · AS OF {websiteData.as_of}</strong><span>Five hypothetical members total 3.5 MIT reference demand units under unmeasured example weights. The 25 MW target is confirmed as total facility supply/design power, not IT load. Design power is not average electricity use. Current modeled MW have no location-based adjustment because project permissions and workload hours are unknown.</span></div>; }
const phase1Base = websiteData.scenario_outputs.find(row => row.year === 2030 && row.case === "base")!;
const categoryLabels: Record<string,string> = { training:"Training",fine_tuning_rl:"Fine-tuning / RL",scientific_ai_hpc:"Scientific AI / HPC",biomedical_private_ai:"Biomedical / private AI",student_faculty_inference:"Student / faculty inference",coding_agents:"Coding / agents",robotics:"Robotics" };
const technologyLabels: Record<string,string> = { fixed_reference:"Fixed reference hardware",illustrative_moderate:"Illustrative moderate efficiency",illustrative_strong:"Illustrative stronger efficiency" };
function Step2Note() { return <div className="step2-note"><strong>STEP 2 ACCOUNTING RULE · {step2Data.as_of}</strong><span>Each modeled device-hour is assigned to one primary compute task. Biomedical and robotics are nonadditive tags; coding agents are an inference subtype with distinct incremental requests assumed. The B200/H200 mix and all MW outputs remain illustrative.</span><a href="https://orcd-docs.mit.edu/running-jobs/requesting-resources/" target="_blank" rel="noreferrer">MIT resource guide</a></div>; }

function Overview() {
  const kpis = ["Validated capacity", "Recommended location", "GPU capacity", "10-year TCO", "Delivery date"];
  return <>
    <div className="hero"><div className="hero-top"><span className="hero-kicker">INVESTMENT COMMITTEE WORKING FILE</span><Tag>Research in progress</Tag></div><h2>University Consortium<br /><em>AI Data Center</em></h2><p>A decision framework for shared AI infrastructure. The 25 MW target means total facility supply and design capacity; whether to reserve or build that capacity remains subject to demand, power and financial underwriting.</p><div className="hero-bottom"><span>Confirmed power definition</span><strong>25 MW</strong><span>Total facility, not IT load</span></div></div>
    <div className="kpi-grid">{kpis.map((label) => <Panel key={label} className="kpi"><span>{label}</span><strong>TBD</strong><small>Pending analysis</small></Panel>)}</div>
    <div className="phase1-callout"><div><span>CURRENT CONDITIONAL SCENARIO · 2030 BASE</span><strong>{phase1Base.facility_design_mw.toFixed(1)} MW</strong></div><p>Five hypothetical members total 3.5 MIT reference demand units. The model assigns hours to mutually exclusive compute tasks. Using PUE {modelInputs.infrastructure.pue.toFixed(2)} as a provisional planning factor, 25 MW total facility power suggests about {(modelInputs.facility_target_mw/modelInputs.infrastructure.pue).toFixed(2)} MW of IT design capacity, pending engineering validation. The expansion decision remains open. <Link href="/demand">Review assumptions <ArrowUpRight size={14}/></Link></p></div>
    <div className="two-col"><Panel><SectionHead eyebrow="DECISION AT A GLANCE" title="Executive recommendation" note="This block will hold the final board level recommendation after the evidence is reviewed."/><div className="decision-list">{[["WHY", "Demand and strategic need"],["WHERE", "Eligible geographic shortlist"],["HOW", "Cloud, dedicated colo or owned facility"],["WHEN", "Power and construction sequence"],["ECONOMICS", "Cost and utilization threshold"]].map(([a,b])=><div key={a}><b>{a}</b><span>{b}</span><Placeholder /></div>)}</div></Panel><Panel className="dark-panel"><div className="eyebrow">CURRENT STATUS</div><h2>Questions before commitment</h2><ol><li>How much compute does a realistic consortium need by 2030?</li><li>Which workloads have geographic or security constraints?</li><li>When could firm power become available?</li><li>At what utilization does ownership outperform alternatives?</li></ol><Link href="/demand" className="text-link">Start with demand <ChevronRight size={16}/></Link></Panel></div>
    <Next slug="demand" label="Demand model" />
  </>;
}

function Demand() {
  const rows = websiteData.scenario_outputs.filter(row =>
    (row.year === 2027 && row.case === "base") || row.year === 2030 ||
    (row.year === 2035 && (row.case === "base" || row.case === "high"))
  );
  const profiles = modelInputs.consortium_member_profiles;
  const categoryRows = modelInputs.display_categories.map(category => {
    const hours = websiteData.workload_outputs.filter(item => item.year === 2030 && item.case === "base" && item.category === category.id);
    return { id: category.id, role: category.role, device: hours[0]?.device ?? "", hours: hours.reduce((sum,item) => sum + item.shared_gpu_hours, 0) };
  });
  return <>
    <ResearchNote/><Step2Note/>
    <div className="flow">{["Members", "Workloads", "GPU / CPU hours", "Hardware", "MW"].map((item,i)=><div className="flow-step" key={item}><span>0{i+1}</span><strong>{item}</strong><small>{i===4?"Illustrative model output":"Source + assumption"}</small></div>)}</div>
    <div className="two-col">
      <Panel><SectionHead eyebrow="CONSORTIUM MIX · EXAMPLE ASSUMPTION" title="Five members, different demand strengths" note="The weights represent effective compute demand relative to one MIT reference unit. They are not population ratios or measured usage."/>
        <div className="model-rows">{profiles.map((profile,i)=><div key={profile.id}><span>{i===0?"Frontier research anchor":i<3?`Research-intensive member ${i}`:`Research + teaching member ${i-2}`}</span><strong>{profile.effective_demand_vs_mit_reference.toFixed(2)}×</strong></div>)}<div><span>Combined MIT reference demand units</span><strong>{modelInputs.consortium_mit_equivalents.toFixed(2)}</strong></div></div>
        <p className="source-small">MIT provides a scale anchor; <a href="https://www.bu.edu/tech/support/research/rcs/publications-and-grants/facilities/" target="_blank" rel="noreferrer">Boston University RCS</a> shows that university platforms vary. Neither source validates the 0.75 or 0.50 weights.</p>
      </Panel>
      <Panel><SectionHead eyebrow="2030 BASE · ASSUMPTION / ESTIMATE" title="From hours to design MW" note="B200 and H200 device-hours remain separate and are not equivalent compute units."/>
        <div className="model-rows"><div><span>B200 shared GPU-hours / year</span><strong>{(phase1Base.shared_B200_gpu_hours/1e6).toFixed(2)}M</strong></div><div><span>H200 shared GPU-hours / year</span><strong>{(phase1Base.shared_H200_gpu_hours/1e6).toFixed(2)}M</strong></div><div><span>CPU-only core-hours / year</span><strong>{(phase1Base.cpu_core_hours/1e6).toFixed(2)}M</strong></div><div><span>Facility design power</span><strong>{phase1Base.facility_design_mw.toFixed(2)} MW</strong></div><div><span>Headroom vs 25 MW envelope</span><strong>{phase1Base.headroom_mw.toFixed(2)} MW</strong></div></div>
      </Panel>
    </div>
    <Panel><SectionHead eyebrow="STEP 2 · EXCLUSIVE COMPUTE ACCOUNTING" title="Seven display categories, five modeled activity groups" note="2030 base device-hours are assumption-driven estimates within each GPU class, not observed workload shares. Biomedical and robotics are tags applied to primary tasks and add no separate hours."/>
      <Table><TableHeader><TableRow><TableHead>Display category</TableHead><TableHead>Accounting role</TableHead><TableHead>Illustrative 2030 device-hours</TableHead><TableHead>Evidence</TableHead></TableRow></TableHeader><TableBody>{categoryRows.map(row=><TableRow key={row.id}><TableCell className="table-strong">{categoryLabels[row.id]}</TableCell><TableCell>{row.role === "domain_or_governance_tag" || row.role === "domain_tag" ? "Nonadditive tag" : row.role === "inference_subtype" ? "Inference subtype" : "Primary compute task"}</TableCell><TableCell>{row.hours ? `${row.device} · ${(row.hours/1e6).toFixed(2)}M` : "No separate hours"}</TableCell><TableCell><Placeholder label={row.hours ? "Model assumption" : "Project data TBD"} /></TableCell></TableRow>)}</TableBody></Table>
      <p className="source-small">Coding agents are assumed to be requests distinct from general assistant inference; request IDs must verify that separation. Biomedical and robotics workloads should be tagged to training, fine-tuning, scientific computing or inference. Real-time robot control stays local by default; shared training, simulation and offline work require project evidence. <a href="https://orcd.mit.edu/news/orcd-newsletter-july-2025" target="_blank" rel="noreferrer">MIT job report</a> does not provide these category hours.</p>
    </Panel>
    <Panel><SectionHead eyebrow="CONDITIONAL RANGE · ASSUMPTION / ESTIMATE" title="2027–2035 capacity stress tests" note="Five hypothetical members total 3.5 MIT reference demand units in every row. Growth multipliers and hardware mapping are assumptions, not forecasts."/>
      <Table><TableHeader><TableRow><TableHead>Year / case</TableHead><TableHead>B200 GPUs</TableHead><TableHead>H200 GPUs</TableHead><TableHead>CPU-only cores</TableHead><TableHead>Facility design MW</TableHead><TableHead>vs 25 MW</TableHead></TableRow></TableHeader><TableBody>{rows.map(row=><TableRow key={`${row.year}-${row.case}`}><TableCell className="table-strong">{row.year} · {row.case}</TableCell><TableCell>{row.B200_gpu_count.toLocaleString()}</TableCell><TableCell>{row.H200_gpu_count.toLocaleString()}</TableCell><TableCell>{row.cpu_only_cores.toLocaleString()}</TableCell><TableCell>{row.facility_design_mw.toFixed(2)}</TableCell><TableCell>{row.headroom_mw>=0?`${row.headroom_mw.toFixed(2)} headroom`:`${Math.abs(row.headroom_mw).toFixed(2)} short`}</TableCell></TableRow>)}</TableBody></Table>
      <p className="source-small">Next validation: named members, 12–24 months of job and cloud records, workload-specific GPU performance, and peak concurrency. The 25 MW target is confirmed as total facility design power. Dividing by assumed PUE {modelInputs.infrastructure.pue.toFixed(2)} gives an indicative {(modelInputs.facility_target_mw/modelInputs.infrastructure.pue).toFixed(2)} MW IT capacity for planning only; peak electrical and cooling ratings need engineering validation.</p>
    </Panel>
    <Next slug="architecture" label="Architecture" />
  </>;
}

function GpuTierAudit() {
  const mix = websiteData.primary_task_mix_outputs.filter(row => row.year === 2030 && row.case === "base");
  const order = ["scientific_ai_hpc", "fine_tuning_rl", "training", "inference"];
  const names: Record<string,string> = { scientific_ai_hpc:"Scientific AI / HPC", fine_tuning_rl:"Fine-tuning / RL", training:"Training", inference:"General inference + coding agents" };
  const qualification: Record<string,string> = {
    scientific_ai_hpc: gpuTierAudit.rows.find(row => row.display_category === "scientific_ai_hpc")!.qualification_measurements,
    fine_tuning_rl: gpuTierAudit.rows.find(row => row.display_category === "fine_tuning_rl")!.qualification_measurements,
    training: gpuTierAudit.rows.find(row => row.display_category === "training")!.qualification_measurements,
    inference: "self-hosted token volume; model size; peak concurrency; latency; SaaS share",
  };
  const sorted = order.map(task => mix.find(row => row.primary_compute_task === task)!);
  return <Panel className="tier-audit"><SectionHead eyebrow="MODEL ASSUMPTION · 2030 BASE" title="Audit H200 scientific jobs and B200 fine-tuning first" note="These four mutually exclusive task groups total about 26.02 million reference GPU device-hours in the current model. Shares describe assumed device occupancy across two hardware classes; they are not observed usage or equivalent compute output."/><Table><TableHeader><TableRow><TableHead>Validation order</TableHead><TableHead>Primary compute task</TableHead><TableHead>Modeled share</TableHead><TableHead>Reference tier</TableHead><TableHead>Qualification evidence needed</TableHead></TableRow></TableHeader><TableBody>{sorted.map((row,i)=><TableRow key={row.primary_compute_task}><TableCell><span className={i<2?"audit-priority":"audit-review"}>{i<2?`Priority ${i+1}`:"Review"}</span></TableCell><TableCell className="table-strong">{names[row.primary_compute_task]}</TableCell><TableCell>{row.share_of_shared_reference_gpu_hours_pct.toFixed(1)}%</TableCell><TableCell>{row.reference_device} · assumed</TableCell><TableCell className="measure-cell">{qualification[row.primary_compute_task]}</TableCell></TableRow>)}</TableBody></Table><p className="source-small">Scientific AI/HPC needs proof of FP64, peak memory, bandwidth or CPU alternatives before assigning H200. Fine-tuning/RL needs full-versus-parameter-efficient method, rollout split and parallelism before assigning B200. MIT reports L40S job counts, not GPU-hours or MW by tier; its job-count share cannot be used as a power share. <a href="https://orcd.mit.edu/news/orcd-newsletter-july-2025" target="_blank" rel="noreferrer">MIT ORCD July 2025</a>.</p></Panel>;
}

function FacilityPowerBridge() {
  const pue = modelInputs.infrastructure.pue;
  const itCapacity = modelInputs.facility_target_mw / pue;
  const b200Nodes = phase1Base.B200_gpu_count / modelInputs.hardware_reference.B200.gpus_per_node;
  const h200Nodes = phase1Base.H200_gpu_count / modelInputs.hardware_reference.H200.gpus_per_node;
  return <Panel className="power-bridge"><SectionHead eyebrow="CONFIRMED DEFINITION · PLANNING ESTIMATE" title="From reference equipment to a 25 MW facility envelope" note="25 MW is the total facility supply/design target. PUE 1.20 is used here as a provisional facility-power overhead factor; the resulting IT limit is a planning estimate, not an engineered peak, UPS or cooling rating."/><div className="metric-strip"><div><span>Facility target</span><strong>{modelInputs.facility_target_mw.toFixed(0)} MW</strong></div><div><span>Estimated IT capacity</span><strong>{itCapacity.toFixed(2)} MW</strong></div><div><span>2030 base IT design</span><strong>{phase1Base.it_design_mw.toFixed(2)} MW</strong></div><div><span>Indicative IT space</span><strong>{(itCapacity-phase1Base.it_design_mw).toFixed(2)} MW</strong></div></div><p className="source-small">The fixed-reference case has {b200Nodes.toLocaleString()} B200 and {h200Nodes.toLocaleString()} H200 eight-GPU nodes. Rack count, distribution, redundancy and cooling remain TBD pending engineering review. PUE is primarily an annual energy ratio; using it to translate design power requires an engineered load schedule. <a href="https://www.energy.gov/sites/default/files/2024-07/best-practice-guide-data-center-design.pdf" target="_blank" rel="noreferrer">US DOE data center design guide</a>.</p></Panel>;
}

function RequirementsMatrix() {
  const dimensions = [
    ["Security & data", "security_gate"],
    ["Latency", "latency_gate"],
    ["Data movement", "data_gravity_gate"],
    ["GPU selection", "gpu_freshness_gate"],
    ["Reliability", "reliability_gate"],
    ["Utilization", "utilization_gate"],
  ] as const;
  return <Panel className="requirements-matrix"><SectionHead eyebrow="CONDITIONAL REQUIREMENTS · POLICY REVIEW PENDING" title="Qualify each workload before placing it" note="These are questions to test, not approved consortium policy or service levels. Biomedical and robotics are nonadditive labels on primary tasks; coding agents are a subtype of inference."/><div className="requirements-grid">{requirementsData.rows.map(row=><article className="requirements-card" key={row.display_category}><div className="requirements-card-head"><h3>{categoryLabels[row.display_category]}</h3><span>{row.accounting_role.replaceAll("_", " ")}</span></div><dl>{dimensions.map(([label,key])=><div key={key}><dt>{label}</dt><dd>{row[key]}</dd></div>)}</dl><div className="requirements-geo">Planning geography <Placeholder label={row.display_category === "biomedical_private_ai" ? "Secure if approved" : row.display_category === "robotics" ? "Local control · US batch" : "US candidate · review"} /></div></article>)}</div><p className="source-small">Security and geography require each project's data owner, agreements, jurisdiction, access controls and service targets. <a href="https://orcd.mit.edu/resources/data-policies" target="_blank" rel="noreferrer">MIT ORCD's current general-system data policy</a> applies to that platform, not every university or the proposed consortium. <a href="https://www.grants.nih.gov/policy-and-compliance/policy-topics/sharing-policies/accessing-data/requirements" target="_blank" rel="noreferrer">NIH controlled-access requirements</a> require dataset-specific review. A US consortium-owned center is a planning candidate for approved restricted work in an isolated secure zone and other permitted work in a general zone. Ownership does not grant dataset access; unapproved data stay at origin. Cloud, dedicated colo, own and hybrid remain to be compared.</p></Panel>;
}

function Architecture() {
  const stack = [["Compute", "GPU mix, CPU / GPU ratio, refresh cadence"],["Data", "Storage tiers, throughput, retention"],["Connectivity", "Campus fiber, interconnect, latency"],["Facility", "Rack density, liquid cooling, PUE"]];
  const technologyRows = websiteData.technology_sensitivity_outputs.filter(row => row.year === 2030 && row.case === "base");
  return <><ResearchNote/><Step2Note/><GpuTierAudit/><Panel className="architecture-summary"><SectionHead eyebrow="2026 HARDWARE REFERENCE · 2030 BASE ASSUMPTION" title="Illustrative compute footprint" note="The same B200/H200 reference design is held constant across years for a capacity stress test, not a future procurement forecast."/><div className="metric-strip"><div><span>B200 GPUs</span><strong>{phase1Base.B200_gpu_count.toLocaleString()}</strong></div><div><span>H200 GPUs</span><strong>{phase1Base.H200_gpu_count.toLocaleString()}</strong></div><div><span>CPU-only cores</span><strong>{phase1Base.cpu_only_cores.toLocaleString()}</strong></div><div><span>IT design load</span><strong>{phase1Base.it_design_mw.toFixed(2)} MW</strong></div><div><span>Facility at PUE {modelInputs.infrastructure.pue.toFixed(2)}</span><strong>{phase1Base.facility_design_mw.toFixed(2)} MW</strong></div></div><p className="source-small">B200 and H200 node specifications: <a href="https://docs.nvidia.com/dgx/dgxb200-user-guide/introduction-to-dgxb200.html" target="_blank" rel="noreferrer">NVIDIA DGX B200</a> and <a href="https://docs.nvidia.com/dgx/dgxh100-user-guide/introduction-to-dgxh100.html" target="_blank" rel="noreferrer">NVIDIA DGX H200</a>. Network/storage allowance and CPU watts per core are unverified assumptions.</p></Panel><FacilityPowerBridge/><Panel className="technology-panel"><SectionHead eyebrow="ASSUMPTION-ONLY GPU EFFICIENCY SENSITIVITY" title="What if equivalent work needs fewer GPU hours?" note="The first row holds reference equipment fixed. Other rows vary effective throughput and maximum node power by assumed factors, while CPU demand, network/storage allowance and PUE stay fixed. They are not future product specifications or forecasts."/><Table><TableHeader><TableRow><TableHead>2030 base equipment assumption</TableHead><TableHead>Effective throughput / GPU</TableHead><TableHead>Node max power</TableHead><TableHead>Reference-class equivalent GPUs · B200 / H200</TableHead><TableHead>Facility design MW</TableHead></TableRow></TableHeader><TableBody>{technologyRows.map(row=><TableRow key={row.technology_case}><TableCell className="table-strong">{technologyLabels[row.technology_case]}</TableCell><TableCell>{row.throughput_per_gpu_vs_reference.toFixed(2)}×</TableCell><TableCell>{row.node_max_power_vs_reference.toFixed(2)}×</TableCell><TableCell>{row.reference_class_B200_gpu_count.toLocaleString()} / {row.reference_class_H200_gpu_count.toLocaleString()}</TableCell><TableCell>{row.facility_design_mw.toFixed(2)} MW</TableCell></TableRow>)}</TableBody></Table><p className="source-small">Only the fixed row describes B200/H200 reference equipment counts. Alternative counts are reference-class equivalents under hypothetical factors; real products need workload benchmarks, memory, network and peak-concurrency checks. <a href="https://mlcommons.org/benchmarks/training/" target="_blank" rel="noreferrer">MLCommons Training</a> and <a href="https://mlcommons.org/working-groups/benchmarks/inference/" target="_blank" rel="noreferrer">MLPerf Inference</a> illustrate task-specific comparison methods.</p></Panel><Panel className="hardware-check"><SectionHead eyebrow="STEP 2 · HARDWARE SELECTION REVISION" title="Re-test the H200-heavy reference mix" note="MIT's job guide makes L40S the default for many ML jobs, with H200 for higher memory or FP64 needs. This is a resource-selection rule, not a new consortium demand estimate."/><div className="hardware-options"><div><strong>L40S-class candidate</strong><span>Ordinary ML and inference jobs; confirm model size, memory and service target.</span></div><div><strong>H200 candidate</strong><span>Large memory or FP64 jobs; verify from actual job telemetry and benchmarks.</span></div><div><strong>Synchronized training</strong><span>Size the interconnect and GPU class from project runs and peak concurrency.</span></div></div><p className="source-small"><a href="https://orcd-docs.mit.edu/running-jobs/requesting-resources/" target="_blank" rel="noreferrer">MIT ORCD resource guide</a> · <a href="https://www.nvidia.com/en-us/data-center/l40s/" target="_blank" rel="noreferrer">NVIDIA L40S specifications</a>. No hardware-mix-adjusted MW is available.</p></Panel><div className="four-grid">{stack.map(([a,b],i)=><Panel key={a} className="stack-card"><span>0{i+1}</span><h3>{a}</h3><p>{b}</p><Placeholder label={i===0?"Reference only":"Design TBD"} /></Panel>)}</div><RequirementsMatrix/><Panel className="thin-panel"><strong>Architecture decision gate</strong><span>Robot closed-loop control stays on device or campus. If the owned-center option qualifies, approved restricted work may use an isolated zone; other permitted training, simulation and offline work may use its general zone. Dataset permissions, storage, fabric and cooling remain TBD.</span></Panel><Next slug="location" label="Location" /></>;
}

function SiteScreening() {
  const names: Record<string,string> = { TX_ERCOT:"Texas · ERCOT service area", IA_MISO:"Iowa · MISO service area", OH_AEP_PJM:"Central Ohio · AEP / PJM", VA_DOM_PJM:"Virginia · Dominion / PJM" };
  const regions = [...candidateRegions.rows].sort((a,b) => names[a.region_id].localeCompare(names[b.region_id]));
  return <><Panel className="site-screening"><SectionHead eyebrow="STEP 6 · INQUIRY POOL, NOT A RANKING" title="Four US regions for written utility and site inquiries" note="These are broad service-area screens, not named parcels or confirmed sites. No region has a verified 25 MW connection, energization date or data-center tariff."/><Table><TableHeader><TableRow><TableHead>Unranked inquiry region</TableHead><TableHead>2024 state industrial average</TableHead><TableHead>Parcel 25 MW supply</TableHead><TableHead>Energization date</TableHead></TableRow></TableHeader><TableBody>{regions.map(row=><TableRow key={row.region_id}><TableCell className="table-strong">{names[row.region_id]}</TableCell><TableCell>{Number(row.state_industrial_retail_cents_per_kwh).toFixed(2)} ¢/kWh</TableCell><TableCell><Placeholder label="Unknown" /></TableCell><TableCell><Placeholder label="Unknown" /></TableCell></TableRow>)}</TableBody></Table><p className="source-small">The price column is the <a href="https://www.eia.gov/electricity/sales_revenue_price/pdf/table_4.pdf" target="_blank" rel="noreferrer">EIA 2024 full-year state industrial retail average</a>, published in 2025. It is background context, not a current data-center quote, a 2030 forecast or a basis for ranking. Ask utilities for a named parcel, staged total-facility load ramp toward 25 MW, applicable charges, connection upgrades and dated service commitments before scoring any location.</p></Panel><details className="site-diligence"><summary>Written diligence requests · {siteDueDiligence.rows.length} open gates</summary><div>{siteDueDiligence.rows.map(row=><article key={row.gate_id}><strong>{row.dimension.replaceAll("_", " ")}</strong><span>{row.requested_evidence}</span><Placeholder label="Not requested" /></article>)}</div></details></>;
}

function Location() {
  const criteria = ["Power availability", "Time to power", "Fiber & latency", "Cooling / climate", "Permitting", "Climate & operational risk"];
  const ruleLabels: Record<string,string> = { LOCAL_CLOSED_LOOP:"Closed-loop control", RESTRICTED_APPROVED:"Approved restricted data", RESTRICTED_NOT_APPROVED:"Transfer not approved", US_SHARED_BATCH:"Permitted batch work", US_SHARED_INTERACTIVE:"Permitted interactive work" };
  const ruleStatus: Record<string,string> = { device_or_campus:"Device / campus", origin_institution:"Origin institution", us_owned_secure_enclave:"Secure zone candidate", us_owned_general_compute:"General zone candidate" };
  return <><ResearchNote/><Panel className="location-scope"><SectionHead eyebrow="USER-SELECTED PLANNING ASSUMPTION" title="Test a US owned center with project-level access gates" note="The geographic screening case is a consortium-owned US facility with a general compute zone and a possible isolated secure environment. Ownership is not yet the final delivery decision; on-site closed-loop control and datasets without transfer approval stay at the device or originating institution."/><div className="location-paths location-paths-three"><div><span>01 / DEVICE OR ORIGIN</span><h3>Keep near the source</h3><p>Robot and instrument closed-loop control; restricted datasets whose terms do not permit transfer or processing at the center.</p><small>Check control timing, failure behavior, dataset terms and the responsible institution.</small></div><div><span>02 / US OWNED CENTER</span><h3>Secure zone candidate</h3><p>Restricted human genomic or clinical compute only when the specific dataset, users and responsible institution are approved for this environment.</p><small>Confirm agreements, isolation, audit, access controls and any inter-institution service terms.</small></div><div><span>03 / US OWNED CENTER</span><h3>General zone candidate</h3><p>Permitted training, fine-tuning, scientific batch work, inference, coding agents and robot training or simulation.</p><small>Confirm project permission, transfer time, latency, availability and equipment fit.</small></div></div><p className="source-small">Owning a center would not grant data access or approve any specific dataset. Restricted work may qualify for its secure zone after project-level review; it is not automatically excluded from center power demand. The US-only site search is a project scope choice, not a claim that public data must legally remain in the US. <a href="https://grants.nih.gov/policy-and-compliance/policy-topics/sharing-policies/accessing-data/using-genomic-data" target="_blank" rel="noreferrer">NIH guidance on third-party systems</a> · <a href="https://www.hhs.gov/hipaa/for-professionals/special-topics/health-information-technology/cloud-computing/index.html" target="_blank" rel="noreferrer">HHS HIPAA cloud guidance</a>.</p></Panel><Panel className="location-rules"><SectionHead eyebrow="ELIGIBILITY DECISION TREE" title="Approve the workload before scoring a city" note="Five conditional rules separate physical proximity from data permission. None records approval for a real dataset."/><div className="location-rule-grid">{eligibilityRules.rows.map((rule,i)=><div key={rule.rule_id}><span>0{i+1}</span><strong>{ruleLabels[rule.rule_id]}</strong><p>{rule.workload_component}</p><small>{rule.validation_needed}</small><Placeholder label={ruleStatus[rule.planning_location]}/></div>)}</div></Panel><Panel className="thin-panel"><strong>Demand model boundary</strong><span>The illustrative 2030 base remains {phase1Base.facility_design_mw.toFixed(2)} MW of facility design power. Project-level permissions and hours are unavailable, so no location-based MW adjustment has been made. Approved restricted work could run in a secure zone if that option is selected and qualified; unapproved work and closed-loop control remain at origin. The estimate is not validated transferable demand.</span></Panel><SiteScreening/><Panel><SectionHead eyebrow="US SITE SCORING FRAMEWORK" title="Evidence before a ranked shortlist" note="Only parcels that pass written power, network, cooling, permitting and workload-permission gates will be scored. Weights and thresholds remain TBD."/><div className="model-rows">{criteria.map(x=><div key={x}><span>{x}</span><Placeholder label="Weight TBD" /></div>)}</div></Panel><Next slug="economics" label="Economics" /></>;
}

function Economics() {
  return <><div className="four-grid">{[["Cloud", "On-demand and reserved compute"],["Colo / Dedicated", "Leased facility and dedicated hardware"],["Own", "Owned facility and infrastructure"],["Hybrid", "Task-specific split across eligible options"]].map(([a,b])=><Panel key={a} className="option"><span>DELIVERY MODEL</span><h3>{a}</h3><p>{b}</p><strong>TBD</strong></Panel>)}</div><Panel><SectionHead eyebrow="COMPARATIVE UNDERWRITING" title="One set of assumptions, four delivery models" note="Cloud, dedicated colo, own and hybrid options will be compared over the same demand, utilization and refresh scenarios. Secure-zone isolation, audit, storage and redundancy costs remain TBD. The 25 MW target refers to total facility supply; energy cost needs an operating load profile, not design power alone."/><div className="metric-strip">{["10-year TCO", "NPV", "$ / GPU-hour", "Utilization break-even"].map(x=><div key={x}><span>{x}</span><strong>TBD</strong></div>)}</div></Panel><Panel className="refresh-panel"><SectionHead eyebrow="FUTURE 10-YEAR TCO INPUT" title="Compare batch refresh policies" note="The financial model will separately test 3-, 4- and 5-year GPU refresh cycles by procurement batch. None is selected, and no refresh cost or TCO is calculated yet."/><div className="refresh-options"><span>3 years · TBD</span><span>4 years · TBD</span><span>5 years · TBD</span></div></Panel><div className="two-col"><Panel><SectionHead eyebrow="KEY INPUTS" title="Cost drivers"/><div className="model-rows">{["GPU and networking capex", "Power tariff and PUE", "Facility / colo costs", "Secure-zone isolation, audit, storage and redundancy", "Cloud price and discount", "Refresh and residual value", "Financing and discount rate"].map(x=><div key={x}><span>{x}</span><Placeholder /></div>)}</div></Panel><Panel><SectionHead eyebrow="SENSITIVITY" title="Where the answer may change"/><div className="chart-placeholder"><span>Cost vs. utilization chart</span><strong>TBD</strong><small>Awaiting validated model inputs</small></div></Panel></div><Next slug="risk-delivery" label="Risk & Delivery" /></>;
}

function RiskDelivery() {
  return <><div className="risk-grid">{[["01", "Power availability", "Firm capacity, price and interconnection"],["02", "GPU supply & obsolescence", "Procurement, lifecycle and refresh"],["03", "Demand & utilization", "Adoption and contracted usage"],["04", "Permitting", "Land use, approvals and schedule"]].map(([n,a,b])=><Panel key={a} className="risk-card"><span>{n} / RISK</span><h3>{a}</h3><p>{b}</p><div>Likelihood <Placeholder /> <span>Impact</span> <Placeholder /></div></Panel>)}</div><Panel><SectionHead eyebrow="DELIVERY ROADMAP" title="1–3+ year planning horizon" note="Dates and gates depend on the selected site, firm supply for the 25 MW total facility target, engineered IT/cooling loads and procurement strategy."/><div className="timeline">{[["Year 1", "Demand validation, consortium alignment, site screening"],["Year 2", "Power, design, permitting and procurement"],["Year 3+", "Construction, commissioning and phased ramp"]].map(([a,b])=><div key={a}><strong>{a}</strong><span>{b}</span><Placeholder label="Timing TBD" /></div>)}</div></Panel><Next slug="scenario-lab" label="Scenario Lab" /></>;
}

const initialInputs = {
  memberAnchor: String(modelInputs.consortium_member_profiles[0].effective_demand_vs_mit_reference),
  memberResearchA: String(modelInputs.consortium_member_profiles[1].effective_demand_vs_mit_reference),
  memberResearchB: String(modelInputs.consortium_member_profiles[2].effective_demand_vs_mit_reference),
  memberMixedA: String(modelInputs.consortium_member_profiles[3].effective_demand_vs_mit_reference),
  memberMixedB: String(modelInputs.consortium_member_profiles[4].effective_demand_vs_mit_reference),
  demandMultiplier: String(modelInputs.scenarios.find(item => item.year === 2030 && item.case === "base")!.demand_multiplier),
  b200Utilization: String(modelInputs.hardware_reference.B200.schedulable_utilization * 100),
  h200Utilization: String(modelInputs.hardware_reference.H200.schedulable_utilization * 100),
  pue: String(modelInputs.infrastructure.pue),
  technologyCase: "fixed_reference",
};
type ScenarioInputs = typeof initialInputs;
type SavedScenario = { id: string; name: string; updatedAt?: string };
const memberKeys = ["memberAnchor", "memberResearchA", "memberResearchB", "memberMixedA", "memberMixedB"] as const;
function parsedScenario(input: ScenarioInputs) {
  if (!input || memberKeys.some(key => input[key] === undefined)) return null;
  const memberWeights = memberKeys.map(key => Number(input[key]));
  const values = { memberWeights, demandMultiplier: Number(input.demandMultiplier), b200Utilization: Number(input.b200Utilization)/100, h200Utilization: Number(input.h200Utilization)/100, pue: Number(input.pue) };
  if (!memberWeights.every(weight => Number.isFinite(weight) && weight >= 0 && weight <= 2) || memberWeights.reduce((sum,weight)=>sum+weight,0)<=0 || !Object.values(values).filter(value => typeof value === "number").every(Number.isFinite) || values.demandMultiplier<=0 || values.demandMultiplier>10 || values.b200Utilization<=0 || values.b200Utilization>1 || values.h200Utilization<=0 || values.h200Utilization>1 || values.pue<1 || values.pue>3) return null;
  const technology = modelInputs.technology_sensitivities.find(item => item.id === input.technologyCase);
  if (!technology) return null;
  const factors = technology.factors_by_year["2030"];
  return calculatePhase1({ ...values, technologyThroughput: factors.throughput_per_gpu, technologyNodePower: factors.node_max_power });
}
function ScenarioLab() {
  const [inputs, setInputs] = useState<ScenarioInputs>(initialInputs);
  const [name, setName] = useState("2030 mixed-member base · illustrative");
  const [message, setMessage] = useState("");
  const [saved, setSaved] = useState<SavedScenario[]>([]);
  const [selected, setSelected] = useState("");
  const [compared, setCompared] = useState<{ name: string; facilityMw: number } | null>(null);
  useEffect(() => {
    type ToolContext = { registerTool: (tool: {name:string;title:string;description:string;inputSchema:object;annotations:object;execute:(input:unknown)=>unknown}, options:{signal:AbortSignal})=>void|Promise<void> };
    const context=(document as Document & {modelContext?:ToolContext}).modelContext;
    if(!context?.registerTool)return;
    const controller=new AbortController();
    const tool={name:"set_scenario_assumptions",title:"Set scenario assumptions",description:"Stage five member weights, a demand multiplier, GPU utilization, PUE and a hypothetical GPU efficiency case in Scenario Lab.",inputSchema:{type:"object",properties:{memberWeights:{type:"array",minItems:5,maxItems:5,items:{type:"number",minimum:0,maximum:2}},demandMultiplier:{type:"number",exclusiveMinimum:0,maximum:10},b200Utilization:{type:"number",exclusiveMinimum:0,maximum:100},h200Utilization:{type:"number",exclusiveMinimum:0,maximum:100},pue:{type:"number",minimum:1,maximum:3},technologyCase:{type:"string",enum:["fixed_reference","illustrative_moderate","illustrative_strong"]}},required:["memberWeights","demandMultiplier","b200Utilization","h200Utilization","pue","technologyCase"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:(input:unknown)=>{const item=input as Record<string,unknown>;if(!Array.isArray(item.memberWeights)||item.memberWeights.length!==5)throw new Error("Provide five member weights.");const next={memberAnchor:String(item.memberWeights[0]),memberResearchA:String(item.memberWeights[1]),memberResearchB:String(item.memberWeights[2]),memberMixedA:String(item.memberWeights[3]),memberMixedB:String(item.memberWeights[4]),demandMultiplier:String(item.demandMultiplier),b200Utilization:String(item.b200Utilization),h200Utilization:String(item.h200Utilization),pue:String(item.pue),technologyCase:String(item.technologyCase)};const output=parsedScenario(next);if(!output)throw new Error("Invalid scenario assumptions.");setInputs(next);setMessage("Illustrative assumptions updated.");return {status:"staged",effectiveDemandUnits:Number(output.effectiveDemandUnits.toFixed(2)),facilityDesignMw:Number(output.facilityMw.toFixed(2)),asOf:websiteData.as_of,classification:"illustrative assumption"};}};
    try{void Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}
    return()=>controller.abort();
  },[]);
  const result = parsedScenario(inputs);
  const selectedTechnology = modelInputs.technology_sensitivities.find(item => item.id === inputs.technologyCase);
  const technologyFactors = selectedTechnology?.factors_by_year["2030"];
  const fixedTechnology = inputs.technologyCase === "fixed_reference";
  const memberFields = [["memberAnchor","Frontier research anchor"],["memberResearchA","Research-intensive member A"],["memberResearchB","Research-intensive member B"],["memberMixedA","Research + teaching member A"],["memberMixedB","Research + teaching member B"]] as const;
  const modelFields = [["demandMultiplier","Demand vs 2027 base","×"],["b200Utilization","B200 schedulable utilization","%"],["h200Utilization","H200 schedulable utilization","%"],["pue","Facility PUE","ratio"]] as const;
  async function refreshSaved() { try { const response=await fetch("/api/scenarios"); const data=await response.json() as {error?:string;scenarios?:SavedScenario[]}; if(!response.ok) throw new Error(data.error); setSaved(data.scenarios||[]); setMessage((data.scenarios||[]).length?"Choose a saved scenario to load or compare.":"No saved scenarios yet."); } catch(error) { setMessage(error instanceof Error?error.message:"Saved scenarios are unavailable."); } }
  async function save() { if(!result) {setMessage("Check all inputs before saving.");return;} try {const response=await fetch("/api/scenarios",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name,inputs})});const data=await response.json() as {error?:string;scenario?:SavedScenario};if(!response.ok) throw new Error(data.error);setMessage("Scenario saved.");await refreshSaved();if(data.scenario)setSelected(data.scenario.id);}catch(error){setMessage(error instanceof Error?error.message:"Scenario could not be saved.");}}
  async function retrieve(compare: boolean) { if(!selected){await refreshSaved();return;} try {const response=await fetch(`/api/scenarios/${encodeURIComponent(selected)}`);const data=await response.json() as {error?:string;scenario?:{name:string;inputs:ScenarioInputs}};if(!response.ok) throw new Error(data.error);const loaded=data.scenario;if(!loaded)throw new Error("Scenario not found.");const output=parsedScenario(loaded.inputs);if(!output)throw new Error("This saved scenario uses earlier assumptions. Recreate it with member weights.");if(compare){setCompared({name:loaded.name,facilityMw:output.facilityMw});setMessage("Comparing facility design power only; financial outputs remain TBD.");}else{setInputs(loaded.inputs);setName(loaded.name);setCompared(null);setMessage("Scenario loaded.");}}catch(error){setMessage(error instanceof Error?error.message:"Scenario could not be loaded.");}}
  return <><ResearchNote/><Step2Note/><div className="two-col scenario-layout"><Panel><SectionHead eyebrow="ILLUSTRATIVE MODEL INPUTS" title="Test the mixed-member base case" note="Five hypothetical member weights sum to 3.5 MIT reference demand units. Edit them to stress-test scale; this does not identify actual members or forecast usage."/><label className="field"><span>Scenario name</span><input value={name} onChange={e=>setName(e.target.value)} placeholder="Scenario name" /></label><div className="scenario-subhead">Member demand weights · example assumptions</div><div className="input-grid">{memberFields.map(([key,label])=><label className="field" key={key}><span>{label}</span><div className="input-wrap"><input type="number" min="0" max="2" step="any" value={inputs[key]} onChange={e=>setInputs({...inputs,[key]:e.target.value})} /><small>× MIT ref</small></div></label>)}</div><p className="effective-units">Combined effective demand: <strong>{result?result.effectiveDemandUnits.toFixed(2):"Check inputs"} MIT reference units</strong></p><div className="scenario-subhead">Demand and facility assumptions</div><div className="input-grid">{modelFields.map(([key,label,unit])=><label className="field" key={key}><span>{label}</span><div className="input-wrap"><input type="number" step="any" value={inputs[key]} onChange={e=>setInputs({...inputs,[key]:e.target.value})} /><small>{unit}</small></div></label>)}</div><div className="scenario-subhead">Hypothetical GPU efficiency sensitivity</div><div className="field"><span>2030 equipment assumption</span><Select value={inputs.technologyCase} onValueChange={value=>setInputs({...inputs,technologyCase:value})}><SelectTrigger className="technology-select"><SelectValue placeholder="Choose assumption" /></SelectTrigger><SelectContent>{modelInputs.technology_sensitivities.map(option=><SelectItem key={option.id} value={option.id}>{technologyLabels[option.id]}</SelectItem>)}</SelectContent></Select></div><p className="source-small">{technologyFactors?`Assumed effective throughput ${technologyFactors.throughput_per_gpu.toFixed(2)}× and maximum node power ${technologyFactors.node_max_power.toFixed(2)}× versus reference equipment.`:"Choose an equipment assumption."} These are adjustable pressure tests, not a GPU roadmap or performance prediction.</p><p className="source-small">Biomedical and robotics are nonadditive tags. Coding agents are assumed to be distinct incremental inference requests. Hardware mapping, CPU utilization, CPU-only watts/core and network/storage allowance require validation. The confirmed 25 MW target is total facility design power. PUE is a planning proxy here; IT capacity and headroom need engineering validation. Scenario outputs do not split general-zone, secure-zone or origin workloads because project permissions and hours are unavailable.</p><div className="scenario-actions"><button onClick={save}>Save scenario</button><button className="secondary-button" onClick={()=>retrieve(false)}>Load selected</button><button className="secondary-button" onClick={()=>retrieve(true)}>Compare</button></div>{message&&<p className="inline-note" role="status">{message}</p>}</Panel><div className="scenario-results"><Panel className="dark-panel"><div className="eyebrow">ASSUMPTION / ESTIMATE · AS OF {websiteData.as_of}</div><h2>{name || "Untitled scenario"}</h2><p>Facility design power uses mutually exclusive primary compute activities and the revised member mix. Biomedical and robotics labels add no separate hours. No location-based MW adjustment is applied; approved restricted work could use a secure zone if the owned-center option qualifies, while unapproved work stays at origin. {fixedTechnology?"Counts use fixed B200/H200 reference equipment.":"Counts are reference-class equivalents under hypothetical throughput and node-power factors, not future product counts."}</p><div className="scenario-result-rows"><div><span>Effective demand units</span><strong>{result?result.effectiveDemandUnits.toFixed(2):"Check inputs"}</strong></div><div><span>IT design power</span><strong>{result?`${result.itMw.toFixed(2)} MW`:"Check inputs"}</strong></div><div><span>Facility design power</span><strong>{result?`${result.facilityMw.toFixed(2)} MW`:"Check inputs"}</strong></div><div><span>Indicative IT capacity at selected PUE</span><strong>{result?`${result.itCapacityMw.toFixed(2)} MW`:"TBD"}</strong></div><div><span>Indicative IT space</span><strong>{result?`${result.itHeadroomMw.toFixed(2)} MW`:"TBD"}</strong></div><div><span>{fixedTechnology?"B200 / H200 reference GPUs":"B200 / H200 reference-class equivalents"}</span><strong>{result?`${result.b200Count.toLocaleString()} / ${result.h200Count.toLocaleString()}`:"TBD"}</strong></div><div><span>Headroom vs 25 MW boundary</span><strong>{result?`${result.headroomMw.toFixed(2)} MW`:"TBD"}</strong></div><div><span>General / secure / origin load split</span><strong>TBD</strong></div><div><span>10-year TCO / NPV</span><strong>TBD</strong></div></div>{compared&&<div className="comparison"><span>COMPARE WITH {compared.name}</span><strong>{compared.facilityMw.toFixed(2)} MW</strong><small>{result?`${(result.facilityMw-compared.facilityMw).toFixed(2)} MW difference`:""}</small></div>}</Panel><Panel><div className="eyebrow">SAVED SCENARIOS</div><div className="saved-controls"><select value={selected} onChange={e=>setSelected(e.target.value)} aria-label="Saved scenario"><option value="">Choose a scenario</option>{saved.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><button onClick={refreshSaved}>Refresh list</button></div>{saved.length===0&&<div className="empty-state"><Database size={28}/><strong>No scenarios loaded</strong><span>Save this case or refresh the account-backed list.</span></div>}</Panel></div></div></>;
}

function ResearchAssistant({ section }: { section: string }) {
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState("");
  const [busy, setBusy] = useState(false);
  async function submit(e: React.FormEvent) {
    e.preventDefault(); if (!prompt.trim()) return;
    setBusy(true); setResponse("");
    try { const r=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:prompt,context:{section,scenarioInputs:null,researchSources:[]}})}); const d=await r.json() as {reply?:string;error?:string}; setResponse(d.reply || d.error || "Chat is not available yet."); }
    catch { setResponse("Chat is not available yet."); } finally { setBusy(false); }
  }
  return <Sheet><SheetTrigger className="assistant-trigger"><Bot size={18}/><span>AI Research Assistant</span></SheetTrigger><SheetContent className="assistant-sheet"><SheetHeader><SheetTitle>AI Research Assistant</SheetTitle><SheetDescription>Research context and scenario inputs can be passed here as the model is developed.</SheetDescription></SheetHeader><div className="assistant-body"><div className="assistant-intro"><CircleHelp size={22}/><strong>Integration ready</strong><p>Chat requires a server-side API key and approved research context. Until then, no AI answer or unsupported research finding is shown.</p></div>{response&&<div className="chat-response" role="status">{response}</div>}</div><form className="assistant-form" onSubmit={submit}><label htmlFor="chat-prompt" className="sr-only">Ask a research question</label><textarea id="chat-prompt" value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Ask about the decision framework…" /><button disabled={busy || !prompt.trim()} aria-label="Send question"><Send size={17}/></button></form></SheetContent></Sheet>;
}

export function SiteView({ section }: { section: string }) {
  const active = sections.find(s=>s.slug===section) || sections[0];
  const [menu, setMenu] = useState(false);
  const content: Record<string, React.ReactNode> = { overview:<Overview/>,demand:<Demand/>,architecture:<Architecture/>,location:<Location/>,economics:<Economics/>,"risk-delivery":<RiskDelivery/>,"scenario-lab":<ScenarioLab/> };
  return <div className="site-shell"><div className="topline"/><header className="site-header"><Link href="/" className="brand"><span className="brand-mark">UC</span><span><strong>University Consortium</strong><small>AI INFRASTRUCTURE STRATEGY</small></span></Link><div className="header-right"><span className="document-status"><span/> WORKING DRAFT · REVISED DEMAND</span><ResearchAssistant section={section}/><button className="menu-button" onClick={()=>setMenu(!menu)} aria-label={menu?"Close navigation":"Open navigation"}>{menu?<X size={20}/>:<Menu size={20}/>}</button></div></header><nav className={`site-nav ${menu?"nav-open":""}`} aria-label="Main navigation">{sections.map(s=><Link key={s.slug} href={path(s.slug)} onClick={()=>setMenu(false)} className={active.slug===s.slug?"active":""}><small>{s.number}</small>{s.label}</Link>)}</nav><main className="main-content"><div className="page-heading"><div><div className="eyebrow">{active.number} / DECISION FRAMEWORK</div><h1>{active.label}</h1><p>{active.question}</p></div><div className="page-heading-right"><Tag>{["demand","architecture","scenario-lab"].includes(section)?"Illustrative estimates":"Decision data TBD"}</Tag><span>25 MW = confirmed total facility target</span></div></div>{content[active.slug]}</main><footer><span>University Consortium AI Data Center · Research framework</span><span>Illustrative estimates as of {websiteData.as_of}; power design and other decisions TBD</span></footer></div>;
}
